namespace Kora {
 public class Manager : Window {
  readonly Store store;State state;Grid shell;StackPanel content,nav;DateTime selected=DateTime.Today;int view;DateTime stamp;DispatcherTimer timer;EventWaitHandle wake;
  public Manager(Store storage,bool preview) {
   store=storage;state=store.Read();Title="Kora Desk · 刻序";Width=1040;Height=Math.Min(790,SystemParameters.WorkArea.Height);MinWidth=800;MinHeight=580;ResizeMode=ResizeMode.CanMinimize;WindowStartupLocation=WindowStartupLocation.CenterScreen;
   shell=new Grid();shell.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(205)});shell.ColumnDefinitions.Add(new ColumnDefinition());
   var side=new Grid{Background=Ui.Soft,Margin=new Thickness(1)};side.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});side.RowDefinitions.Add(new RowDefinition());side.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});
   var brand=new StackPanel{Margin=new Thickness(26,36,20,35)};var logo=Ui.Text("kora",34);logo.FontWeight=FontWeights.SemiBold;brand.Children.Add(logo);var label=Ui.Text("刻 序  /  DESK",11,Ui.Muted);label.Margin=new Thickness(2,5,0,0);brand.Children.Add(label);side.Children.Add(brand);Ui.Drag(this,brand);
   nav=new StackPanel{Margin=new Thickness(14,0,14,0)};Grid.SetRow(nav,1);side.Children.Add(nav);
   var bottom=new StackPanel{Margin=new Thickness(26,20,22,27)};bottom.Children.Add(Ui.Text("一点一点，\n也是向前。",17,Ui.Accent));var local=Ui.Text("●  只在本机，安心记录",11,Ui.Muted);local.Margin=new Thickness(0,18,0,0);bottom.Children.Add(local);Grid.SetRow(bottom,2);side.Children.Add(bottom);shell.Children.Add(side);
   var area=new Grid();area.RowDefinitions.Add(new RowDefinition{Height=new GridLength(45)});area.RowDefinitions.Add(new RowDefinition());Grid.SetColumn(area,1);shell.Children.Add(area);
   var bar=new DockPanel{LastChildFill=false,Margin=new Thickness(20,7,10,0)};var close=Ui.Button("×",Close);close.FontSize=20;close.ToolTip="关闭管理窗口，桌面组件继续运行";DockPanel.SetDock(close,Dock.Right);bar.Children.Add(close);var minimize=Ui.Button("−",()=>WindowState=WindowState.Minimized);DockPanel.SetDock(minimize,Dock.Right);bar.Children.Add(minimize);var grip=Ui.Text("YOUR DAY, AT YOUR PACE.",10,Ui.Muted);grip.VerticalAlignment=VerticalAlignment.Center;bar.Children.Add(grip);Ui.Drag(this,grip);area.Children.Add(bar);
   content=new StackPanel{Margin=new Thickness(34,14,34,25)};var scroll=new ScrollViewer{Content=content};Grid.SetRow(scroll,1);area.Children.Add(scroll);Ui.WindowFrame(this,shell);Draw();
   wake=new EventWaitHandle(false,EventResetMode.AutoReset,"Local\\KoraDesk.Manager.Wake");timer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(1)};timer.Tick+=delegate { if(wake.WaitOne(0)){Show();WindowState=WindowState.Normal;Activate();} var current=File.GetLastWriteTimeUtc(store.FilePath);if(current!=stamp){Ui.Guard(delegate{state=store.Read();stamp=current;Draw();});} if(selected==lastToday&&DateTime.Today!=lastToday){selected=DateTime.Today;lastToday=DateTime.Today;Draw();} };timer.Start();Closed+=delegate{timer.Stop();wake.Dispose();};
   if(!preview)Loaded+=delegate{Ui.Guard(()=>Launch.App("Kora.Widget.exe"));if(store.RecoveryNotice!=null)MessageBox.Show(this,store.RecoveryNotice,"数据恢复");};
  }
  DateTime lastToday=DateTime.Today;
  void Reload(){state=store.Read();stamp=File.GetLastWriteTimeUtc(store.FilePath);Draw();}
  void Edit(TaskItem task){new Editor(this,store,task,selected).ShowDialog();Reload();}
  void Draw(){nav.Children.Clear();string[] names={"◷   每日清单","▦   每周计划","⚙   偏好设置"};for(int i=0;i<3;i++){int index=i;var b=Ui.Button(names[i],()=>{view=index;Draw();});b.Margin=new Thickness(0,4,0,4);b.HorizontalContentAlignment=HorizontalAlignment.Left;b.Padding=new Thickness(16,13,10,13);b.Background=view==i?Brushes.White:Brushes.Transparent;b.FontWeight=view==i?FontWeights.SemiBold:FontWeights.Normal;nav.Children.Add(b);}content.Children.Clear();if(view==0)DrawDay();else if(view==1)DrawPlan();else DrawSettings();}
  void Heading(string small,string title,string subtitle){var kicker=Ui.Text(small,11,Ui.Accent);kicker.FontWeight=FontWeights.SemiBold;content.Children.Add(kicker);var h=Ui.Text(title,29);h.FontWeight=FontWeights.SemiBold;h.Margin=new Thickness(0,9,0,9);content.Children.Add(h);var sub=Ui.Text(subtitle,13,Ui.Muted);sub.Margin=new Thickness(0,0,0,17);content.Children.Add(sub);}
  void DrawDay(){var tasks=state.ForDay(selected);int done=tasks.Count(t=>state.IsDone(t,selected));Heading(selected.ToString("M 月 d 日")+"  /  "+Dates.Short[(int)selected.DayOfWeek],selected==DateTime.Today?"今天，慢慢做好。":selected.ToString("M 月 d 日")+"的安排",done==tasks.Count&&tasks.Count>0?"今天的清单已经完成。把剩下的时间留给自己。":"不必一下完成所有事。从眼前这一件开始。");
   var summary=new Grid();summary.ColumnDefinitions.Add(new ColumnDefinition());summary.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var progress=new StackPanel();var line=Ui.Text("今日进度",12,Ui.Muted);progress.Children.Add(line);var count=Ui.Text(done+" / "+tasks.Count+"  已完成",23,Ui.Accent);count.FontWeight=FontWeights.SemiBold;count.Margin=new Thickness(0,5,0,10);progress.Children.Add(count);var track=new Grid{Height=4,Background=Ui.Line,HorizontalAlignment=HorizontalAlignment.Left,Width=260};var fill=new Border{Background=Ui.Accent,CornerRadius=new CornerRadius(2),HorizontalAlignment=HorizontalAlignment.Left,Width=tasks.Count==0?0:260.0*done/tasks.Count};track.Children.Add(fill);progress.Children.Add(track);summary.Children.Add(progress);var add=Ui.Button("＋  添加任务",()=>Edit(null),true);add.VerticalAlignment=VerticalAlignment.Center;Grid.SetColumn(add,1);summary.Children.Add(add);content.Children.Add(Ui.Card(summary,new Thickness(21,17,21,17)));
   var week=new Grid{Margin=new Thickness(0,14,0,8)};for(int i=0;i<7;i++)week.ColumnDefinitions.Add(new ColumnDefinition());var monday=Dates.Monday(selected);for(int i=0;i<7;i++){var day=monday.AddDays(i);var label=new StackPanel();label.Children.Add(Ui.Text(Dates.Short[(int)day.DayOfWeek],11,selected==day?Brushes.White:Ui.Muted));var n=Ui.Text(day.Day.ToString("00"),18,selected==day?Brushes.White:Ui.Ink);n.Margin=new Thickness(0,5,0,0);label.Children.Add(n);var b=Ui.Button("",()=>{selected=day;Draw();});b.Content=label;b.Background=selected==day?Ui.Accent:Brushes.Transparent;b.Margin=new Thickness(3,0,3,0);b.Padding=new Thickness(8,10,8,10);Grid.SetColumn(b,i);week.Children.Add(b);}content.Children.Add(week);
   var dateNav=new DockPanel{LastChildFill=false,Margin=new Thickness(0,0,0,0)};var next=Ui.Button("下周  →",()=>{selected=selected.AddDays(7);Draw();});DockPanel.SetDock(next,Dock.Right);dateNav.Children.Add(next);var today=Ui.Button("回到今天",()=>{selected=DateTime.Today;Draw();});DockPanel.SetDock(today,Dock.Right);dateNav.Children.Add(today);dateNav.Children.Add(Ui.Button("←  上周",()=>{selected=selected.AddDays(-7);Draw();}));content.Children.Add(dateNav);
   foreach(var group in tasks.GroupBy(t=>t.Group)){var head=new DockPanel{Margin=new Thickness(2,8,2,8)};head.Children.Add(Ui.Text(group.Key+"  /  "+(group.Key=="学习"?"STUDY":group.Key=="健身"?"MOVEMENT":"LIFE"),11,Ui.Muted));content.Children.Add(head);var rows=new StackPanel();foreach(var t in group){var task=t;rows.Children.Add(Ui.TaskRow(task,state.IsDone(task,selected),value=>{store.Update(s=>s.SetDone(task.Id,selected,value));Reload();},()=>Edit(task),false));}content.Children.Add(Ui.Card(rows,new Thickness(16,6,10,6)));}
   if(tasks.Count==0){var empty=Ui.Text("这一天留白。\n添加一件小事，或安心休息。",18,Ui.Muted);empty.Margin=new Thickness(0,40,0,30);empty.TextAlignment=TextAlignment.Center;content.Children.Add(empty);}
  }
  void DrawPlan(){Heading("A WEEK WITH INTENTION","让每周，自有节奏。","每天重复，或每周轮换。所有安排都可以随时调整。");var add=Ui.Button("＋  添加任务",()=>Edit(null),true);add.HorizontalAlignment=HorizontalAlignment.Left;add.Margin=new Thickness(0,0,0,22);content.Children.Add(add);
   foreach(var g in state.Tasks.GroupBy(t=>t.Group)){Ui.Label(content,g.Key+"  ·  "+g.Count()+" 项安排");var rows=new StackPanel();foreach(var t in g){var task=t;var row=new DockPanel{Margin=new Thickness(0,6,0,6)};var edit=Ui.Button("编辑",()=>Edit(task));DockPanel.SetDock(edit,Dock.Right);row.Children.Add(edit);var copy=new StackPanel{Margin=new Thickness(0,4,12,4)};copy.Children.Add(Ui.Text(task.Title,15));var sub=Ui.Text(task.Frequency,12,Ui.Muted);sub.Margin=new Thickness(0,5,0,0);copy.Children.Add(sub);row.Children.Add(copy);rows.Children.Add(row);}content.Children.Add(Ui.Card(rows,new Thickness(20,8,12,8)));}}
  void DrawSettings(){Heading("MAKE ROOM FOR YOUR DAY","轻一点，刚刚好。","桌面组件只保留当天清单。复杂的安排，留在这里。");var box=new StackPanel();box.Children.Add(Ui.Text("桌面组件",18));var desc=Ui.Text("默认留在桌面层，其他应用可以盖住它。\n打开置顶后，组件会显示在其他窗口之上。",13,Ui.Muted);desc.Margin=new Thickness(0,10,0,18);box.Children.Add(desc);var top=new CheckBox{Content="始终置顶",IsChecked=state.Settings.AlwaysOnTop,Margin=new Thickness(0,0,0,18)};top.Click+=delegate{Ui.Guard(()=>{store.Update(s=>s.Settings.AlwaysOnTop=top.IsChecked==true);Reload();});};box.Children.Add(top);var actions=new WrapPanel();actions.Children.Add(Ui.Button("显示桌面组件",()=>Launch.App("Kora.Widget.exe"),true));var reset=Ui.Button("重置组件位置",()=>{store.Update(s=>{s.Settings.X=-9999;s.Settings.Y=-9999;});Launch.App("Kora.Widget.exe");Reload();});reset.Margin=new Thickness(8,0,0,0);actions.Children.Add(reset);box.Children.Add(actions);content.Children.Add(Ui.Card(box,new Thickness(24)));
   var data=new StackPanel{Margin=new Thickness(0)};data.Children.Add(Ui.Text("属于你的记录",18));var privacy=Ui.Text("任务与完成记录仅保存在这台电脑。无需账号，没有广告，应用不连接网络。自动保留上一次保存的备份。",13,Ui.Muted);privacy.Margin=new Thickness(0,10,0,18);data.Children.Add(privacy);var buttons=new WrapPanel();buttons.Children.Add(Ui.Button("导出备份",Export));buttons.Children.Add(Ui.Button("导入备份",Import));buttons.Children.Add(Ui.Button("打开数据文件夹",()=>Launch.Folder(store.Folder)));data.Children.Add(buttons);var card=Ui.Card(data,new Thickness(24));card.Margin=new Thickness(0,16,0,0);content.Children.Add(card);
   var about=Ui.Text("Kora Desk · 刻序\nv1.0.0  /  一点一点，也是向前。\n拖动组件顶部可移动位置；右键托盘图标可隐藏组件或退出。",12,Ui.Muted);about.Margin=new Thickness(3,24,0,0);content.Children.Add(about);
  }
  void Export(){var dialog=new SaveFileDialog{Filter="Kora 备份 (*.json)|*.json",FileName="kora-backup-"+Dates.Key(DateTime.Today)+".json"};if(dialog.ShowDialog(this)==true){store.Export(dialog.FileName);MessageBox.Show(this,"备份已导出。","Kora Desk");}}
  void Import(){var dialog=new OpenFileDialog{Filter="Kora 备份 (*.json)|*.json"};if(dialog.ShowDialog(this)!=true)return;Store.Decode(File.ReadAllBytes(dialog.FileName));if(MessageBox.Show(this,"用这个备份替换现有任务和完成记录？当前数据将保留为自动备份。","导入备份",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;store.Import(dialog.FileName);Reload();}
 }
 public static class Program {
  [STAThread] public static int Main(string[] args){bool preview=args.Contains("--preview");Mutex mutex=null;try {bool first;mutex=new Mutex(true,"Local\\KoraDesk.Manager",out first);if(!first&&!preview){using(var e=EventWaitHandle.OpenExisting("Local\\KoraDesk.Manager.Wake"))e.Set();return 0;}var app=new Application{ShutdownMode=ShutdownMode.OnMainWindowClose};Ui.Init(app);var win=new Manager(new Store(),preview);if(preview)win.Loaded+=delegate {win.Dispatcher.BeginInvoke(new Action(()=>{Ui.Snapshot(win,Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"manager.png"));win.Close();}),DispatcherPriority.ApplicationIdle);};app.Run(win);return 0;}catch(Exception e){if(preview){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"preview-error.txt"),e.ToString());return 1;}MessageBox.Show(e.Message,"Kora Desk · 无法启动",MessageBoxButton.OK,MessageBoxImage.Warning);return 1;}finally{if(mutex!=null)mutex.Dispose();}}
 }
}
